"""英語系・社会系7教科（eigo_c1, eigo_c2, ronri_e1, ronri_e2, rekishi, sekaishi, koukyou）の問題生成スクリプト。"""

from __future__ import annotations

import hashlib
import random
from collections import Counter

# 教科ごとの単元ID定義（data/subjects.json と完全一致させる）
SUBJECT_UNITS: dict[str, list[str]] = {
    "eigo_c1": ["eigo_c1-u1", "eigo_c1-u2", "eigo_c1-u3"],
    "eigo_c2": ["eigo_c2-u1", "eigo_c2-u2", "eigo_c2-u3"],
    "ronri_e1": ["ronri_e1-u1", "ronri_e1-u2", "ronri_e1-u3", "ronri_e1-u4"],
    "ronri_e2": ["ronri_e2-u1", "ronri_e2-u2", "ronri_e2-u3"],
    "rekishi": ["rekishi-u1", "rekishi-u2", "rekishi-u3"],
    "sekaishi": ["sekaishi-u1", "sekaishi-u2", "sekaishi-u3", "sekaishi-u4"],
    "koukyou": ["koukyou-u1", "koukyou-u2", "koukyou-u3"],
}


def _stable_shuffle(items: list[str], key: str) -> list[str]:
    """問題文に紐づく決定論的シードを用いて選択肢をシャッフルする。"""
    digest = hashlib.sha256(key.encode("utf-8")).hexdigest()
    rng = random.Random(int(digest[:16], 16))
    copied = list(items)
    rng.shuffle(copied)
    return copied


def mc(
    unit_id: str,
    difficulty: int,
    question: str,
    answer: str,
    distractors: list[str] | tuple[str, str, str],
    explanation: str,
) -> dict:
    """4択問題（選択）の辞書を生成する。"""
    choices_raw = [answer, *distractors]
    if len(choices_raw) != 4 or len(set(choices_raw)) != 4:
        raise ValueError(f"選択肢が4つ一意ではありません: {question} -> {choices_raw}")
    if any(not c.strip() for c in choices_raw):
        raise ValueError(f"空の選択肢があります: {question}")
    return {
        "subjectId": unit_id.split("-")[0],
        "unitId": unit_id,
        "type": "選択",
        "difficulty": difficulty,
        "question": question,
        "answer": answer,
        "choices": _stable_shuffle(choices_raw, question),
        "explanation": explanation,
    }


def wr(
    unit_id: str,
    difficulty: int,
    question: str,
    answer: str,
    explanation: str,
    alts: list[str] | None = None,
) -> dict:
    """記述問題の辞書を生成する。"""
    if not answer.strip():
        raise ValueError(f"空の正解があります: {question}")
    item: dict = {
        "subjectId": unit_id.split("-")[0],
        "unitId": unit_id,
        "type": "記述",
        "difficulty": difficulty,
        "question": question,
        "answer": answer,
        "explanation": explanation,
    }
    if alts:
        clean_alts = [a for a in dict.fromkeys(alts) if a.strip() and a != answer]
        if clean_alts:
            item["alternativeAnswers"] = clean_alts
    return item


def tf(
    unit_id: str,
    difficulty: int,
    question: str,
    is_true: bool,
    explanation: str,
) -> dict:
    """○×問題の辞書を生成する。"""
    return {
        "subjectId": unit_id.split("-")[0],
        "unitId": unit_id,
        "type": "○×",
        "difficulty": difficulty,
        "question": question,
        "answer": "○" if is_true else "×",
        "explanation": explanation,
    }


