        mc(u2, 2, "次の英文の空所に入る最も適切な語を選べ。\nDoctors made a quick (   ) based on the blood test.", "diagnosis", ("conservation", "contamination", "extinction"), "diagnosis は「診断」。動詞は diagnose。"),
        mc(u2, 2, "次の英文の空所に入る最も適切な語を選べ。\nThis discovery was a major (   ) in cancer research.", "breakthrough", ("inequality", "phenomenon", "drought"), "breakthrough は「（科学などの）飛躍的進歩・突破口」。"),
        mc(u2, 2, "次の英文の空所に入る最も適切な語を選べ。\nWe should eliminate racial (   ) and treat everyone equally.", "discrimination", ("innovation", "welfare", "agriculture"), "discrimination は「差別」。動詞 discriminate against 〜（〜を差別する）。"),
        mc(u2, 2, "次の英文の空所に入る最も適切な語を選べ。\nThe country is facing rapid (   ) as young people move to big cities.", "urbanization", ("deforestation", "automation", "conservation"), "urbanization は「都市化」。urban（都市の）から派生。"),
        mc(u2, 2, "次の英文の空所に入る最も適切な語を選べ。\nRoads, bridges, and water systems are basic social (   ).", "infrastructure", ("biodiversity", "ethnicity", "stereotype"), "infrastructure は「インフラ（社会基盤）」。"),
        mc(u2, 2, "次の英文の空所に入る最も適切な語を選べ。\nMany people were forced to leave their homes and became (   ).", "refugees", ("consumers", "corporations", "minorities"), "refugee は「難民」。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nIndustrial waste can (   ) rivers and underground water.", "contaminate", ("conserve", "simulate", "cultivate"), "contaminate は「〜を汚染する・汚す」。pollute の類義語。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nAurora is a natural (   ) seen in polar regions.", "phenomenon", ("mechanism", "institution", "currency"), "phenomenon は「現象」（複数形は phenomena）。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nHigh (   ) rates help citizens understand complex news.", "literacy", ("scarcity", "poverty", "drought"), "literacy は「読み書きの能力・（特定の分野の）活用能力」。media literacy など。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nWe need to bridge the economic (   ) between rich and poor areas.", "gap", ("bond", "draft", "core"), "economic gap で「経済格差」。bridge the gap で「格差を埋める」。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nHaving (   ) allows us to understand how others feel.", "empathy", ("prejudice", "extinction", "emission"), "empathy は「共感（他人の感情を理解する力）」。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nRapid (   ) has changed factory work by using robots instead of humans.", "automation", ("conservation", "agriculture", "democracy"), "automation は「自動化・オートメーション」。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nThe organization works for the (   ) of ancient temples.", "conservation", ("contamination", "discrimination", "drought"), "conservation は「保護・保存（自然環境や文化財など）」。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nModern technology can (   ) real-world conditions on a computer.", "simulate", ("emit", "contaminate", "vaccinate"), "simulate は「〜を模擬実験する・シミュレートする」。"),
        # 記述 (18問)
        wr(u2, 1, "「地球温暖化」を英語2語で答えよ。", "global warming", "global（地球規模の）＋ warming（温暖化）で global warming。"),
        wr(u2, 1, "「気候変動」を英語2語で答えよ。", "climate change", "climate（気候）＋ change（変化）で climate change。"),
        wr(u2, 1, "「温室効果」を表す英語表現を完成させよ。\nThe (   ) effect traps heat in the Earth's atmosphere.", "greenhouse", "greenhouse effect で「温室効果」。"),
        wr(u2, 1, "「人工知能（AI）」の正式名称を英語2語で答えよ。", "artificial intelligence", "artificial（人工の）＋ intelligence（知能）で AI。"),
        wr(u2, 1, "「（生物の）生息地・自生地」を意味する h で始まる英語の名詞（単数形）を答えよ。", "habitat", "habitat は「生息地・生息環境」。"),
        wr(u2, 1, "「貧困」を意味する p で始まる英語の名詞を答えよ。", "poverty", "poverty は「貧困」。形容詞 poor に対応する名詞。"),
        wr(u2, 2, "「多様性」を意味する d で始まる英語の名詞を答えよ。", "diversity", "diversity は「多様性」。形容詞は diverse（多様な）。"),
        wr(u2, 2, "「不平等・格差」を意味する i で始まる英語の名詞を答えよ。", "inequality", "equality（平等）に否定の in- がついた語。"),
        wr(u2, 2, "「民主主義」を意味する d で始まる英語の名詞を答えよ。", "democracy", "democracy は「民主主義・民主政治」。形容詞は democratic。"),
        wr(u2, 2, "「農業」を意味する a で始まる英語の名詞を答えよ。", "agriculture", "agriculture は「農業」。industry（工業）と対比してよく出る。"),
        wr(u2, 2, "「生態系」を意味する e で始まる英語の名詞（単数形）を答えよ。", "ecosystem", "ecosystem は「生態系」（eco + system）。"),
        wr(u2, 2, "「絶滅」を意味する e で始まる英語の名詞を答えよ。", "extinction", "extinction は「絶滅」。become extinct / face extinction などで使う。"),
        wr(u2, 2, "「干ばつ・ひでり」を意味する d で始まる英語の名詞（単数形）を答えよ。", "drought", "drought は「干ばつ」。flood（洪水）の対義語として環境トピックで頻出。"),
        wr(u2, 3, "「情報格差（デジタルデバイド）」を表す英語2語を完成させよ。\nThe digital (   ) is a gap in access to modern technology.", "divide", "digital divide で「情報格差・デジタルデバイド」。"),
        wr(u2, 3, "「正確な・精密な」を意味する p で始まる英語の形容詞を答えよ。", "precise", "precise は「正確な・精密な」。exact や accurate の類義語。"),
        wr(u2, 3, "「人口統計上の・人口動態の」を意味する d で始まる英語の形容詞を答えよ。", "demographic", "demographic shift（人口動態の変化）のように使われる重要語。"),
        wr(u2, 3, "「（文化的・歴史的な）遺産」を意味する h で始まる英語の名詞を答えよ。", "heritage", "World Heritage（世界遺産）や cultural heritage（文化遺産）で頻出。"),
        wr(u2, 3, "「固定観念」を意味する s で始まる英語の名詞（単数形）を答えよ。", "stereotype", "stereotype は「固定観念・ステレオタイプ」。"),
        # ○× (16問)
        tf(u2, 1, "「recycle」は廃棄物を回収して再び資源として利用することを意味する。", True, "その通り。reuse（再使用）、reduce（削減）と並ぶ 3R の一つ。"),
        tf(u2, 1, "「artificial」は「天然の・自然のままの」という意味の形容詞である。", False, "誤り。artificial は「人工の・人造の」。対義語は natural である。"),
        tf(u2, 1, "「vaccine」は細菌感染症の治療のみに用いる「抗菌薬（抗生物質）」を意味する。", False, "誤り。vaccine は感染症を予防するための「ワクチン」を意味する（抗菌薬・抗生物質は antibiotic）。"),
        tf(u2, 1, "「globalization」は人・モノ・情報・資本が国境を越えて結びつく「グローバル化」を表す。", True, "その通り。国際社会トピックの中心語である。"),
        tf(u2, 1, "「consumer」は商品やサービスを「生産する企業」のことを指す。", False, "誤り。consumer は「消費者」。生産者は producer である。"),
        tf(u2, 2, "「prejudice」は十分な根拠なしに人や集団に対して抱く「偏見」を意味する。", True, "その通り。prejudice against 〜（〜に対する偏見）の形で使う。"),
        tf(u2, 2, "「minority」は社会の中で多数を占める「多数派」のことである。", False, "誤り。minority は「少数派（マイノリティ）」。多数派は majority である。"),
        tf(u2, 2, "「currency」は「現在・現代」のみを意味し、「通貨・貨幣」という意味はもたない。", False, "誤り。currency には「通貨・貨幣」（例: foreign currency「外貨」）や「流通」という意味がある。"),
        tf(u2, 2, "「welfare」は社会保障や福祉を意味し、social welfare（社会福祉）のように使われる。", True, "その通り。国民の幸福や福祉を表す重要名詞である。"),
        tf(u2, 2, "「sustainable」は「一度使ったらすぐ廃棄される・使い捨ての」という意味である。", False, "誤り。sustainable は「持続可能な」。「使い捨ての」は disposable である。"),
        tf(u2, 2, "「data privacy」は個人情報やデータの保護・プライバシーに関する概念である。", True, "その通り。情報社会・AIトピックで頻出する。"),
        tf(u2, 3, "「phenomena」は単数形であり、その複数形が「phenomenon」である。", False, "誤り。逆である。phenomenon が単数形、phenomena が複数形（ギリシア語由来の変化）。"),
        tf(u2, 3, "「gene」は生物の親から子へ伝わる「遺伝子」を意味し、形容詞形は genetic である。", True, "その通り。genetic engineering（遺伝子工学）のように使う。"),
        tf(u2, 3, "「ethnic」は「民族の・人種的な」という意味の形容詞である。", True, "その通り。ethnic group（民族集団）、ethnic food（民族料理）などで使う。"),
        tf(u2, 3, "「corporation」は小規模な個人商店のみを指し、大企業には使われない。", False, "誤り。corporation は「法人・（特に大規模な）企業・株式会社」を指す。"),
        tf(u2, 3, "「ozone layer」は地球の成層圏にあって有害な紫外線を吸収する「オゾン層」を指す。", True, "その通り。環境問題の読解でよく登場する表現。"),

        # --- u3: Lesson 7-10 論理接続・長文読解重要構文/語法 (58問) ---
        mc(u3, 1, "次の英文の空所に入る最も適切な語を選べ。\nIt goes without (   ) that health is more important than wealth.", "saying", ("telling", "speaking", "talking"), "It goes without saying that 〜 で「〜は言うまでもない」。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な語を選べ。\nI couldn't help (   ) when I heard his funny joke.", "laughing", ("to laugh", "laugh", "laughed"), "cannot help -ing で「〜せずにはいられない」。cannot but ＋原形 と書き換え可能。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な語を選べ。\nShe makes it a (   ) to read for thirty minutes every night.", "rule", ("habit", "plan", "way"), "make it a rule to V で「Vすることにしている（習慣にしている）」。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な語を選べ。\nThis old song always reminds me (   ) my childhood.", "of", ("for", "with", "from"), "remind A of B で「AにBを思い出させる」。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な語を選べ。\nThe Internet enables us (   ) connect with people worldwide.", "to", ("for", "of", "at"), "enable O to V で「OがVすることを可能にする」。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な接続副詞を選べ。\nThe task was difficult; (   ), we managed to finish it on time.", "nevertheless", ("therefore", "moreover", "consequently"), "nevertheless は「それにもかかわらず」（逆接の副詞）。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な語を選べ。\nThe more you read, the (   ) you will learn.", "more", ("many", "most", "much"), "The ＋比較級, the ＋比較級 で「〜すればするほど、ますます…」。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な語を選べ。\nHe is likely (   ) win the speech contest.", "to", ("that", "for", "of"), "be likely to V で「Vしそうだ・Vする可能性が高い」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な語を選べ。\nDon't take your parents' help for (   ).", "granted", ("given", "known", "supposed"), "take A for granted で「Aを当然のことと思う」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な前置詞を選べ。\nThe thief robbed the bank (   ) a million yen.", "of", ("from", "with", "for"), "rob 人/場所 of 物 で「人・場所から物を奪う」。steal 物 from 人 と語法を区別する。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な語を選べ。\nYou are (   ) to wear a helmet when riding a bicycle here.", "supposed", ("bound", "tended", "failed"), "be supposed to V で「Vすることになっている・Vするはずだ」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な接続副詞を選べ。\nHe didn't prepare well; (   ), he failed the interview.", "consequently", ("conversely", "meanwhile", "nonetheless"), "consequently は「その結果・したがって」（因果・結果の副詞）。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な語を選べ。\nPeople often mistake me (   ) my twin brother.", "for", ("as", "to", "with"), "mistake A for B で「AをBと間違える」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な語を選べ。\nHoney can be substituted (   ) sugar in this recipe.", "for", ("to", "with", "into"), "substitute A for B で「Bの代わりにAを使う」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な表現を選べ。\nThe conditions changed; (   ), we revised our schedule.", "accordingly", ("on the contrary", "nonetheless", "that is to say"), "accordingly は「それに応じて・したがって」を表す論理接続副詞。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な表現を選べ。\nThe movie was not good at all; it was (   ) entertaining.", "far from", ("bound to", "likely to", "supposed to"), "far from ＋形容詞/-ing で「〜とはほど遠い・決して〜ではない」。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な語を選べ。\n(   ) sooner had I reached the station than the train left.", "No", ("Not", "Hardly", "Scarcely"), "No sooner had S p.p. than S' 過去形 で「〜するとすぐに…」。hardly/scarcely は when と組み合わせる。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な語を選べ。\nReading is to the mind (   ) food is to the body.", "what", ("which", "that", "as"), "A is to B what C is to D で「AのBに対する関係は、CのDに対する関係と同じだ」。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な語を選べ。\n(   ) that he is still young, his performance is remarkable.", "Given", ("Giving", "To give", "Having given"), "Given that S V で「〜を考慮すると・〜だとすると」。前置詞的用法の given も同様。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な語を選べ。\nShe is (   ) a fool; in fact, she is the wisest person I know.", "anything but", ("nothing but", "all but", "something like"), "anything but 〜 で「決して〜ではない」（= never）。nothing but は「〜にすぎない・〜ばかり」。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な表現を選べ。\nI have a lot of work to do today. (   ), I'll finish the email first.", "Meanwhile", ("Conversely", "Strictly speaking", "Namely"), "meanwhile は「その間に・他方では」。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な語を選べ。\nPlease inform me (   ) any changes to the schedule.", "of", ("for", "to", "with"), "inform 人 of 事 で「人に事柄を知らせる・通知する」。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な語を選べ。\nMany people regard failure (   ) a step toward success.", "as", ("for", "to", "into"), "regard A as B で「AをBとみなす」。think of A as B / look on A as B と同義。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な表現を選べ。\nHe wants to study a Romance language, (   ), Spanish or French.", "namely", ("nonetheless", "conversely", "on the whole"), "namely は「すなわち・言い換えると」（具体例・言い換えを導く）。"),
        # 記述 (18問)
        wr(u3, 1, "「さらに・その上」を表す f で始まる論理接続副詞を1語入れよ。\nThe hotel is cheap. (   ), it is very close to the station.", "Furthermore", "furthermore / moreover は「さらに・その上」（追加）。"),
        wr(u3, 1, "「それゆえ・したがって」を表す t で始まる論理接続副詞を1語入れよ。\nThe road was icy; (   ), we drove very slowly.", "therefore", "therefore / thus / hence は「したがって・それゆえ」。"),
        wr(u3, 1, "「〜する傾向がある」を表す表現を完成させよ。\nPeople (   ) to eat more when they feel stressed.", "tend", "tend to V で「Vする傾向がある」。"),
        wr(u3, 1, "「〜をBのせいにする・責める」を表す前置詞を1語入れよ。\nDon't blame others (   ) your own mistakes.", "for", "blame A for B で「BのことでAを責める」。"),
        wr(u3, 1, "「〜しがちである／必ず〜する」を表す表現を完成させよ。\nIf you don't study, you are (   ) to fail.", "bound", "be bound to V で「きっとVする・必ずVする」。"),
        wr(u3, 1, "「全体的には・概して」を表す3語の表現を完成させよ。\nOn the (   ), the event was a great success.", "whole", "on the whole で「全体として・概して」。"),
        wr(u3, 2, "「〜しそこなう・〜しない」を表す動詞を1語入れよ。\nHe (   ) to notice the warning sign.", "failed", "fail to V で「Vしそこなう・Vできない・Vしない」。文脈が過去なら failed。"),
        wr(u3, 2, "「〜にすぎない・〜ばかり」を表す2語の熟語を完成させよ。\nHe cares about (   ) but money.", "nothing", "nothing but 〜 で「〜だけ・〜にすぎない」（= only）。"),
        wr(u3, 2, "「〜と言われているもの・いわゆる」を表す表現を完成させよ。\nHe is (   ) we call a walking dictionary.", "what", "what we call / what is called で「いわゆる」。"),
        wr(u3, 2, "「〜するとすぐに」を表す Hardly ... (   ) の構文を完成させよ。\nHardly had she entered the room (   ) the phone rang.", "when", "Hardly/Scarcely had S p.p. when/before S' 過去形 で「〜するやいなや…」。"),
        wr(u3, 2, "「厳密に言えば」を表す2語の独立分詞構文を完成させよ。\n(   ) speaking, a tomato is a fruit, not a vegetable.", "Strictly", "strictly speaking で「厳密に言えば」。文頭なので大文字 Strictly。"),
        wr(u3, 2, "「〜は言うまでもなく」を表す3語の熟語を完成させよ。\nShe speaks French, to (   ) nothing of English.", "say", "to say nothing of 〜 / not to mention 〜 で「〜は言うまでもなく」。"),
        wr(u3, 2, "「〜にもかかわらず」を表す n で始まる逆接の副詞（1語）を答えよ。", "nevertheless", "nevertheless / nonetheless は「それにもかかわらず」。"),
        wr(u3, 3, "「それとは逆に・反対に」を表す c で始まる論理接続副詞を1語答えよ。", "conversely", "conversely は「逆に・反対に」。"),
        wr(u3, 3, "「要するに・まとめると」を表す2語の表現を完成させよ。\nTo (   ) up, we need better communication.", "sum", "to sum up で「要約すると・要するに」（= in summary）。"),
        wr(u3, 3, "「〜と仮定すると・〜だとすれば」を表す分詞由来の接続表現を完成させよ。\n(   ) that everyone agrees, we will start tomorrow.", "Assuming", "assuming (that) 〜 で「〜と仮定すると」。文頭なので大文字 Assuming。"),
        wr(u3, 3, "「〜するのも当然だ・無理もない」を表す構文を完成させよ。\nIt is no (   ) that she passed with the top score.", "wonder", "It is no wonder (that) 〜 で「〜なのも不思議ではない（当然だ）」。"),
        wr(u3, 3, "「〜を強制する」を表す構文を完成させよ。\nThe heavy snow (   ) us to stay indoors all day.", "forced", "force O to V で「Oに無理やりVさせる」。文脈から過去形 forced。"),
        # ○× (16問)
