        mc(u2, 3, "次の英文の空所に入る最も適切な表現を選べ。\nI (   ) well go home now; it's getting dark.", "may as", ("had better", "would rather", "ought as"), "may as well ＋原形 で「〜したほうがよい・〜するのも悪くない」。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nHow could you (   ) say such a rude thing to your friend?", "possibly", ("maybe", "perhaps", "probably"), "疑問文で can / could とともに用い「いったいどうして〜できようか」と強調する副詞は possibly。"),
        mc(u2, 3, "次の英文の空所に入る最も適切な語を選べ。\nHe insisted that he (   ) innocent of the crime.", "was", ("be", "should be", "is"), "insist の後ろでも「〜すべきだ（提案・要求）」ではなく「〜という事実だ（主張）」の場合は通常の直説法（時制の一致で was）を使う。"),
        # 記述 (14問)
        wr(u2, 1, "「（今は）〜するに違いない」という強い推量の助動詞を1語入れよ。\nHe has a huge house; he (   ) be very rich.", "must", "現在の状態に対する確信度の高い推量には must を使う。"),
        wr(u2, 1, "「以前は毎朝ジョギングをしたものだった（過去の習慣）」を表す助動詞を1語入れよ。\nWhen I was young, I (   ) often go jogging before breakfast.", "would", "過去の反復的な習慣「よく〜したものだ」は would (often) ＋原形で表せる（used to も状態・習慣の両方に可）。", ["used to"]),
        wr(u2, 1, "「（過去に）〜したかもしれない」を表す表現を完成させよ。\nShe is late. She may (   ) missed the bus.", "have", "may have ＋過去分詞 で「（過去に）〜したかもしれない」。"),
        wr(u2, 1, "「私たちは3年前からお互いを知っている」となるように動詞を適切な形に直せ。\nWe (   ) each other for three years. [know]", "have known", "know は状態動詞なので現在完了進行形ではなく現在完了形 have known を使う。"),
        wr(u2, 1, "「宿題を終えてしまうまではテレビを見てはいけない」となるように空所に1語入れよ。\nDon't watch TV until you (   ) your homework.", "finish", "until が導く「時を表す副詞節」の中では未来のことも現在形 finish（または現在完了形 have finished）で表す。", ["have finished"]),
        wr(u2, 2, "「あの電車に間に合ったはずがない」を完成させよ。\nHe (   ) have caught that train because he left too late.", "cannot", "過去の強い否定推量「〜したはずがない」は cannot have ＋過去分詞（can't も可）。", ["can't", "couldn't"]),
        wr(u2, 2, "「その会議に出席すべきではなかった（のに出席してしまった）」を完成させよ。\nI should (   ) have attended that boring meeting.", "not", "should not have ＋過去分詞 で「〜すべきではなかったのに」。"),
        wr(u2, 2, "時制の一致に注意して動詞を適切な形に直せ。\nOur teacher said that the sun (   ) in the east. [rise]", "rises", "不変の真理や自然法則は主節が過去形（said）であっても時制の一致を受けず現在形 rises のままにする。"),
        wr(u2, 2, "「そのニュースを聞いたとき、私はちょうど夕食を食べ終えたところだった」を過去完了形で完成させよ。\nWhen I heard the news, I (   ) just finished dinner.", "had", "過去の時点までにすでに完了していたことは過去完了 had ＋過去分詞で表す。"),
        wr(u2, 2, "「もし明日雨が降らなければ、ハイキングに行きます」の空所に適切な形を入れよ。\nIf it (   ) rain tomorrow, we will go hiking.", "doesn't", "条件を表す if 副詞節なので現在形の否定 doesn't（does not）を使う。", ["does not"]),
        wr(u2, 3, "「会議を延期することが重要だ」の that節内に適切な助動詞1語を入れよ。\nIt is important that the meeting (   ) be postponed.", "should", "It is important / necessary / essential that S (should) V で「〜することが重要だ・必要だ」。"),
        wr(u2, 3, "「映画を見るくらいならむしろ散歩に行きたい」を表す表現を完成させよ。\nI would (   ) go for a walk than watch a movie.", "rather", "would rather A than B で「BするくらいならAしたい」。"),
        wr(u2, 3, "「彼に真実を打ち明けたほうがよい（忠告）」を表す表現を完成させよ。\nYou had (   ) tell him the truth.", "better", "had better ＋原形 で「〜したほうがよい」。"),
        wr(u2, 3, "「ここへ来るのに2時間かかるはずだったのに、渋滞で3時間かかった」の空所に1語入れよ。\nIt was (   ) to take two hours to get here, but it took three.", "supposed", "was supposed to V で「〜するはずだった・予定だった」。"),
        # ○× (12問)
        tf(u2, 1, "「She is knowing the answer.」は「彼女はその答えを今知っている」という正しい現在進行形の文である。", False, "誤り。know は状態動詞なので通常は進行形にせず `She knows the answer.` とする。"),
        tf(u2, 1, "「When I arrived, it had been snowing for two hours.」は「着いた時点で2時間雪が降り続いていた」という意味である。", True, "その通り。過去のある時点までの動作の継続を表す過去完了進行形である。"),
        tf(u2, 1, "「cannot」と「be able to」について、未来形「〜できるだろう」を表すときは `will can` と書く。", False, "誤り。助動詞を2つ並べることはできないため `will be able to` を使う。"),
        tf(u2, 1, "「He has been to Paris twice.」は「彼はパリに2回行ったことがある」という意味である。", True, "その通り。have been to 〜 は「〜へ行ったことがある（経験）」を表す。"),
        tf(u2, 2, "「If he will come tomorrow, I will tell him.」は正しい条件文である。", False, "誤り。条件を表す副詞節（if節）の中では未来のことも現在形（If he comes tomorrow）を使う。"),
        tf(u2, 2, "「must have ＋過去分詞」は「〜しなければならなかった」という過去の義務を表す。", False, "誤り。must have p.p. は「〜したに違いない」という過去への推量。過去の義務は had to V を使う。"),
        tf(u2, 2, "「You might as well throw your money away.」は「お金を捨てるようなものだ（捨てるのも同然だ）」という慣用表現である。", True, "その通り。may/might as well 〜 で「〜したも同然だ／〜するのも悪くない」を表す。"),
        tf(u2, 2, "「used to V」は過去の習慣だけでなく「かつて〜が存在した・〜だった」という過去の状態も表せる。", True, "その通り。would は過去の動作・習慣のみで状態動詞には使えないが、used to は状態にも使える。"),
        tf(u2, 3, "「I didn't need to buy a ticket.」は「買う必要がなかった（ので買わなかった）」という意味で使われることが多い。", True, "その通り。didn't need to V は「必要がなかった（実際しなかった可能性が高い）」、needn't have p.p. は「必要なかったのに実際した」と区別される。"),
        tf(u2, 3, "「No one knows when the package will arrive.」の when節では、未来のことであっても will を省いて arrives にしなければならない。", False, "誤り。ここでの when節は動詞 knows の目的語となる「名詞節（いつ届くか）」なので、未来のことには will arrive を使う。"),
        tf(u2, 3, "「He could pass the exam yesterday.」のように、過去の特定の1回の成功には could を使うのが普通である。", False, "誤り。過去の特定の1回の「実際に〜できた」には could ではなく was able to や managed to を使う（否定 couldn't は可）。"),
        tf(u2, 3, "「It is essential that every student obey the safety rules.」のように、essential などの後の that節では動詞の原形を用いることがある。", True, "その通り。should を省略した仮定法現在（動詞の原形 obey）が使われる。"),

        # --- u3: 不定詞と動名詞 (44問) ---
        mc(u3, 1, "次の英文の空所に入る最も適切な形を選べ。\nShe decided (   ) abroad next year.", "to study", ("studying", "study", "studied"), "decide は目的語に to不定詞のみをとる動詞である（decide to V）。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な形を選べ。\nWould you mind (   ) down the music a little?", "turning", ("to turn", "turn", "turned"), "mind（気にする・嫌がる）は目的語に動名詞（-ing）のみをとる動詞である。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な形を選べ。\nHe gave up (   ) sweets for his health.", "eating", ("to eat", "eat", "eaten"), "give up（あきらめる・やめる）の後ろには動名詞（-ing）を置く。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な前置詞を選べ。\nIt was very kind (   ) you to carry my suitcase.", "of", ("for", "to", "with"), "kind, nice, wise, careless, rude など「人の性質」を表す形容詞の後ろの意味上の主語には of を使う。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な形を選べ。\nThis dictionary is very useful for students (   ) English.", "to learn", ("learning", "learned", "learn"), "It is useful for A to V や名詞を修飾する形など、意味上の主語は通常 for ＋人＋ to V で表す。"),
        mc(u3, 1, "次の英文の空所に入る最も適切な形を選べ。\nI don't know how (   ) this machine.", "to operate", ("operating", "operate", "operated"), "疑問詞＋to不定詞（how to V）で「Vの仕方」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な形を選べ。\nI remember (   ) him at the station last month.", "meeting", ("to meet", "meet", "met"), "remember -ing は「（過去に）〜したことを覚えている」。remember to V は「（これから）忘れずに〜する」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な形を選べ。\nDon't forget (   ) the letter before you go to bed.", "to post", ("posting", "post", "posted"), "forget to V で「（これからすべきことを）〜し忘れる」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な形を選べ。\nOn the way home, he stopped (   ) a cup of coffee.", "to buy", ("buying", "buy", "bought"), "stop to V は「〜するために立ち止まる（副詞的用法）」。stop -ing は「〜するのをやめる」。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な形を選べ。\nHe avoided (   ) my question directly.", "answering", ("to answer", "answer", "answered"), "avoid（避ける）は目的語に動名詞（-ing）のみをとる重要動詞である。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な形を選べ。\nShe pretended (   ) asleep when her mother came in.", "to be", ("being", "be", "been"), "pretend（〜のふりをする）は目的語に to不定詞をとる（pretend to V）。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な形を選べ。\nIt is no use (   ) over spilt milk.", "crying", ("to cry", "cry", "cried"), "It is no use -ing で「〜しても無駄だ」（ことわざ：覆水盆に返らず）。"),
        mc(u3, 2, "次の英文の空所に入る最も適切な語を選べ。\nI feel like (   ) a walk along the river.", "taking", ("to take", "take", "took"), "feel like -ing で「〜したい気がする」。like は前置詞なので動名詞が続く。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な形を選べ。\nHe seems (   ) very hard when he was a college student.", "to have studied", ("to study", "studying", "having studied"), "「（今）〜したように見える（現在より前の過去のこと）」を表すには完了不定詞 to have ＋過去分詞 を使う。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な形を選べ。\nShe is proud of (   ) won first prize in the contest.", "having", ("have", "to have", "had"), "前置詞 of の後ろで、主節よりも前の時を表すには完了動名詞 having ＋過去分詞 を使う。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な形を選べ。\nThis old temple is worth (   ) at least once.", "visiting", ("to visit", "to be visited", "visited"), "be worth -ing で「〜する価値がある」。意味は受動的だが能動の -ing 形をとる点に注意。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な形を選べ。\nMy car needs (   ) as soon as possible.", "washing", ("to wash", "wash", "washed"), "物が主語で need / want / require ＋ -ing は「〜される必要がある（= to be p.p.）」という受動の意味になる。"),
        mc(u3, 3, "次の英文の空所に入る最も適切な表現を選べ。\n(   ) the truth, I don't agree with his opinion.", "To tell", ("Telling", "To say", "Saying"), "独立不定詞 To tell (you) the truth で「実を言うと」。"),
        # 記述 (14問)
        wr(u3, 1, "「彼はサッカーの練習をするのを楽しんだ」となるように動詞を適切な形に直せ。\nHe enjoyed (   ) soccer with his friends. [practice]", "practicing", "enjoy は目的語に動名詞のみをとる（practising も可）。", ["practising"]),
        wr(u3, 1, "「彼女は将来歌手になりたいと思っている」となるように動詞を適切な形に直せ。\nShe hopes (   ) a singer in the future. [become]", "to become", "hope は目的語に to不定詞のみをとる。"),
        wr(u3, 1, "「私はこの計画を延期するべきではない」となるように動詞を適切な形に直せ。\nWe shouldn't put off (   ) a decision. [make]", "making", "句動詞 put off（延期する）の後ろは動名詞になる。"),
        wr(u3, 1, "「何か冷たい飲み物が欲しい」を不定詞の形容詞的用法で完成させよ。\nI want something cold (   ) drink.", "to", "something ＋形容詞＋ to V で「Vするための何か〜」。"),
        wr(u3, 1, "「彼は早起きすることに慣れている」となるように動詞を適切な形に直せ。\nHe is used to (   ) up early. [get]", "getting", "be used to -ing で「〜することに慣れている」。ここでの to は前置詞。"),
        wr(u3, 2, "「彼女はついに自分の間違いを認めた」となるように動詞を適切な形に直せ。\nShe finally admitted (   ) a mistake. [make]", "making", "admit（認める）は目的語に動名詞（または完了動名詞 having made）をとる。", ["having made"]),
        wr(u3, 2, "「彼はテストに合格するために一生懸命勉強した」を表す表現を完成させよ。\nHe studied hard in (   ) to pass the exam.", "order", "in order to V で「Vするために」（目的を明確にする不定詞）。"),
        wr(u3, 2, "「私の娘がピアノを弾くのを聞いていただけますか」の動名詞の意味上の主語を埋めよ。\nWould you mind (   ) daughter playing the piano?", "my", "動名詞の意味上の主語は所有格（または目的格）で表すため my（または me ではなく my daughter）。"),
        wr(u3, 2, "「彼は自分の質問に答えるのを拒んだ」となるように動詞を適切な形に直せ。\nHe refused (   ) my question. [answer]", "to answer", "refuse（断る・拒む）は目的語に to不定詞のみをとる。"),
        wr(u3, 2, "「駅に着くとすぐに私は彼に電話した」を動名詞で表現した空所に前置詞1語を入れよ。\n(   ) arriving at the station, I called him.", "On", "On -ing で「〜するとすぐに」（= As soon as S V）。文頭なので大文字 On（Upon も可）。", ["Upon"]),
        wr(u3, 3, "「私はその計画に賛成しない（反対している）」を表す表現を完成させよ。\nI object (   ) changing the original schedule.", "to", "object to -ing で「〜することに反対する」。to は前置詞。"),
        wr(u3, 3, "「彼は二度と遅刻しないと約束した」となるように否定の不定詞を完成させよ。\nHe promised (   ) to be late again.", "not", "to不定詞の否定は to の直前に not や never を置いて not to V とする。", ["never"]),
        wr(u3, 3, "「言わば（いわば）」を表す独立不定詞を完成させよ。\nBooks are, so to (   ), silent friends.", "speak", "so to speak で「いわば」。"),
        wr(u3, 3, "「その部屋は誰も中に入ってこないように鍵がかけられた」となるように受動不定詞を完成させよ。\nThe room was locked so as (   ) to be entered by anyone.", "not", "否定の「〜しないように」は so as not to V / in order not to V を使う。"),
        # ○× (12問)
        tf(u3, 1, "「finish」の後ろに動作を続けるときは `finish to write` のように to不定詞を使う。", False, "誤り。finish は動名詞のみを目的語にとる動詞（finish writing）である。"),
        tf(u3, 1, "「decide」と「promise」はどちらも目的語に to不定詞をとる動詞である。", True, "その通り。decide to V / promise to V となる。"),
        tf(u3, 1, "「It is difficult for me to solve this problem.」のように、difficult の後ろの意味上の主語には of ではなく for を使う。", True, "その通り。difficult は事柄の難易度を表す形容詞なので for A to V を使う。"),
        tf(u3, 1, "「I need a pen to write.」は「書くためのペンが必要だ」という意味の正しい英文である。", False, "誤り。pen は「書く道具」なので `a pen to write with` のように前置詞 with を補う必要がある。"),
        tf(u3, 2, "「I regret to tell you that 〜」は「残念ながら〜とお知らせしなければなりません」という意味になる。", True, "その通り。regret to V は「これから〜することを残念に思う」、regret -ing は「（過去に）〜したことを後悔する」。"),
        tf(u3, 2, "「I am looking forward to see you soon.」は文法的に正しい英文である。", False, "誤り。look forward to の to は前置詞なので、後ろは動名詞 seeing にしなければならない。"),
        tf(u3, 2, "「try to V」は「〜しようと試みる・努力する」、一方「try -ing」は「試しに〜してみる」という違いがある。", True, "その通り。Try pushing the button.（試しにボタンを押してみて）と区別する。"),
        tf(u3, 2, "「The president is to visit Japan next month.」の be to は「予定（〜することになっている）」を表している。", True, "その通り。be to 不定詞には予定・義務・可能・運命・意図の5つの用法がある。"),
        tf(u3, 3, "「He denied to steal the money.」は「彼は金を盗んだことを否定した」という正しい文である。", False, "誤り。deny（否定する）は目的語に動名詞（stealing / having stolen）をとる動詞であり、to不定詞はとらない。"),
        tf(u3, 3, "「There is no telling what will happen tomorrow.」は「明日何が起こるか分からない」という意味である。", True, "その通り。There is no -ing で「〜することはできない（= It is impossible to V）」。"),
        tf(u3, 3, "「I am sorry for not having replied earlier.」では、not は動名詞 having の直前に置くのが正しい。", True, "その通り。動名詞の否定は not / never を動名詞の直前に置く。"),
        tf(u3, 3, "「Strange to say, nobody noticed the mistake.」の Strange to say は「奇妙な話だが」という独立不定詞である。", True, "その通り。習慣的に文頭などで挿入的に使われる慣用表現。"),

        # --- u4: 比較と関係詞 (44問) ---
        mc(u4, 1, "次の英文の空所に入る最も適切な語を選べ。\nThis river is twice as (   ) as that one.", "long", ("longer", "longest", "more long"), "倍数表現は「倍数＋ as ＋原級＋ as」の語順になるため原級 long を使う。"),
        mc(u4, 1, "次の英文の空所に入る最も適切な語を選べ。\nMt. Fuji is the highest mountain (   ) Japan.", "in", ("of", "among", "than"), "場所・範囲（単数名詞）を表すときは in、複数名詞や同種の集団のときは of を使う。"),
        mc(u4, 1, "次の英文の空所に入る最も適切な語を選べ。\nShe is (   ) taller than her sister.", "much", ("very", "more", "so"), "比較級の強調には much, far, even, a lot, still などを使い、very は使えない。"),
        mc(u4, 1, "次の英文の空所に入る最も適切な関係代名詞を選べ。\nLook at the girl (   ) is playing the violin over there.", "who", ("which", "whose", "whom"), "先行詞が人（the girl）で関係詞節内の主語の働きをするため主格の who（または that）を使う。"),
        mc(u4, 1, "次の英文の空所に入る最も適切な関係代名詞を選べ。\nI have a friend (   ) father is a pilot.", "whose", ("who", "whom", "which"), "「その友人の父親が〜」という所有関係を表すため所有格の関係代名詞 whose を使う。"),
        mc(u4, 1, "次の英文の空所に入る最も適切な関係詞を選べ。\nThis is the city (   ) I was born and raised.", "where", ("which", "who", "what"), "「その街で生まれ育った」という場所の副詞（= in which）にあたるため関係副詞 where を使う。"),
